import{_ as t,o as e,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"故障响应","description":"","frontmatter":{"title":"故障响应","outline":[2,3],"article":{"type":"solution","structure":"solution"}},"headers":[],"relativePath":"frontend/guide/engineering/reliability/incident-response.md","filePath":"frontend/guide/engineering/reliability/incident-response.md","lastUpdated":1785331851000}'),r={name:"frontend/guide/engineering/reliability/incident-response.md"};function l(i,a,d,p,o,h){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="故障响应" tabindex="-1">故障响应 <a class="header-anchor" href="#故障响应" aria-label="Permalink to &quot;故障响应&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>故障响应的首要目标是控制用户影响，而不是在压力下立刻证明唯一根因。有效流程让一个人负责决策、其他人并行调查和缓解、沟通者稳定同步状态、记录者保存证据；所有动作都围绕“当前事实、下一决策点和恢复标准”推进。</p><p>本文覆盖从检测、声明到恢复确认的事故进行期。排班、值班就绪和 Runbook 维护见<a href="/frontend/guide/engineering/reliability/on-call">值班与线上责任</a>；事故结束后才进行的因果分析和行动项见<a href="/frontend/guide/engineering/reliability/postmortem">复盘与改进闭环</a>。</p><h2 id="_1-进入事故流程" tabindex="-1">1. 进入事故流程 <a class="header-anchor" href="#_1-进入事故流程" aria-label="Permalink to &quot;1. 进入事故流程&quot;">​</a></h2><h3 id="_1-1-事故的判定" tabindex="-1">1.1 事故的判定 <a class="header-anchor" href="#_1-1-事故的判定" aria-label="Permalink to &quot;1.1 事故的判定&quot;">​</a></h3><p>以下任一情况应声明事故，而不是继续在个人窗口排查：</p><ul><li>关键用户旅程超过 SLO 或正在快速消耗错误预算。</li><li>影响跨多个服务、地区或团队。</li><li>需要高风险生产操作或多方协调。</li><li>影响范围未知但可能重大。</li><li>安全、隐私、资金或数据正确性存在风险。</li><li>单人处理超过规定时间仍无明确缓解路径。</li></ul><p>声明事故是获得结构和资源的动作，不是对责任或技术能力的评价。宁可早声明后降级，也不要等影响明确扩大才建群。</p><h3 id="_1-2-严重级别" tabindex="-1">1.2 严重级别 <a class="header-anchor" href="#_1-2-严重级别" aria-label="Permalink to &quot;1.2 严重级别&quot;">​</a></h3><p>一份可执行分级：</p><table tabindex="0"><thead><tr><th>级别</th><th>用户影响</th><th>响应要求</th><th>示例</th></tr></thead><tbody><tr><td>SEV1</td><td>核心旅程大面积不可用、数据/资金/安全高风险</td><td>立即全员响应，高频内外沟通</td><td>无法登录、错误扣款、敏感数据泄漏</td></tr><tr><td>SEV2</td><td>重要功能显著受损，存在替代路径或影响部分用户</td><td>立即事故响应，15–30 分钟更新</td><td>批量导出和部分路由不可用</td></tr><tr><td>SEV3</td><td>局部、低比例或非关键功能，工作时间可控</td><td>服务团队处理，按需沟通</td><td>少量浏览器样式异常</td></tr></tbody></table><p>级别按用户影响和紧迫性判断，不按“代码改动大小”或“原因是不是前端”判断。信息变化时可以升降级，并记录原因和时间。</p><h3 id="_1-3-事故声明" tabindex="-1">1.3 事故声明 <a class="header-anchor" href="#_1-3-事故声明" aria-label="Permalink to &quot;1.3 事故声明&quot;">​</a></h3><p>填写后的声明：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ID：INC-2026-0729-01</span></span>
<span class="line"><span>标题：order-web 动态模块加载失败</span></span>
<span class="line"><span>声明时间：2026-07-29 14:05 CST</span></span>
<span class="line"><span>当前级别：SEV2</span></span>
<span class="line"><span>影响：部分已打开页面进入分析页或批量导出时失败</span></span>
<span class="line"><span>已知范围：production；华东、华南均有事件</span></span>
<span class="line"><span>当前 release：order-web@8f3c41a</span></span>
<span class="line"><span>Incident commander：王宁</span></span>
<span class="line"><span>响应频道：#inc-2026-0729-01</span></span>
<span class="line"><span>会议桥：https://meet.example.com/inc-2026-0729-01</span></span>
<span class="line"><span>下一次更新：14:20 CST</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>标题描述用户可观察症状，不在证据不足时写“CDN 删除旧资源导致故障”。</p><h3 id="_1-4-退出条件" tabindex="-1">1.4 退出条件 <a class="header-anchor" href="#_1-4-退出条件" aria-label="Permalink to &quot;1.4 退出条件&quot;">​</a></h3><p>事故不能因为图表“看起来回落”就关闭。预先定义：</p><ul><li>关键 SLI 连续一个观察窗口恢复，例如 10 分钟。</li><li>合成与真实用户探针通过。</li><li>缓解动作完成且没有继续扩大迹象。</li><li>数据一致性和待处理任务已确认。</li><li>用户/内部状态已同步。</li><li>后续观察 owner 和复盘 owner 已明确。</li></ul><h2 id="_2-检测与初始评估" tabindex="-1">2. 检测与初始评估 <a class="header-anchor" href="#_2-检测与初始评估" aria-label="Permalink to &quot;2. 检测与初始评估&quot;">​</a></h2><h3 id="_2-1-信号来源" tabindex="-1">2.1 信号来源 <a class="header-anchor" href="#_2-1-信号来源" aria-label="Permalink to &quot;2.1 信号来源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信号</th><th>优点</th><th>局限</th></tr></thead><tbody><tr><td>SLO 告警</td><td>接近用户旅程、阈值明确</td><td>可能晚于单点错误</td></tr><tr><td>浏览器错误/RUM</td><td>接近真实客户端和 release</td><td>采样、拦截器或上报链也可能失败</td></tr><tr><td>合成监控</td><td>可持续执行固定路径</td><td>覆盖地区和账号有限</td></tr><tr><td>客服/用户反馈</td><td>能发现未观测体验</td><td>信息非结构化且通常较晚</td></tr><tr><td>部署事件</td><td>能关联变更</td><td>相关不等于因果</td></tr></tbody></table><p>同时使用独立信号可以避免把监控系统自身故障误判为产品故障。</p><h3 id="_2-2-初始五问" tabindex="-1">2.2 初始五问 <a class="header-anchor" href="#_2-2-初始五问" aria-label="Permalink to &quot;2.2 初始五问&quot;">​</a></h3><p>值班者在前几分钟回答：</p><ol><li>用户具体无法完成什么？</li><li>从什么时候开始，影响是否仍在扩大？</li><li>哪些环境、地区、浏览器、租户和 release 受影响？</li><li>最近有哪些发布、配置或上游变化？</li><li>有无已知安全、数据或资金风险？</li></ol><p>不知道就写“未知”，不要用猜测填满事故卡。未知项本身决定下一项调查任务。</p><h3 id="_2-3-事实与假设分开" tabindex="-1">2.3 事实与假设分开 <a class="header-anchor" href="#_2-3-事实与假设分开" aria-label="Permalink to &quot;2.3 事实与假设分开&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事实 F1：13:58 起 ChunkLoadError 会话率从 0.04% 升至 3.8%。</span></span>
<span class="line"><span>事实 F2：失败 URL 均返回 404，文件 hash 属于前一 release。</span></span>
<span class="line"><span>事实 F3：13:55 完成 order-web@8f3c41a 部署。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>假设 H1：部署清理删除了仍被旧 HTML 引用的 chunk。</span></span>
<span class="line"><span>假设 H2：某 CDN region 的缓存索引异常。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>每个假设要有验证者和截止时间。不要在状态通告中把假设写成已确认原因。</p><h3 id="_2-4-影响量化" tabindex="-1">2.4 影响量化 <a class="header-anchor" href="#_2-4-影响量化" aria-label="Permalink to &quot;2.4 影响量化&quot;">​</a></h3><p>至少记录：</p><ul><li>受影响会话/用户和总 eligible 会话。</li><li>失败旅程和替代路径。</li><li>开始时间与趋势。</li><li>地区、浏览器、版本和租户分布。</li><li>错误/延迟/数据正确性程度。</li></ul><p>示例：<code>13:58–14:10，2,840 个会话中 500 个发生动态模块 404（17.6%）；订单列表仍可用，分析页和批量导出入口受阻。</code></p><h2 id="_3-响应角色" tabindex="-1">3. 响应角色 <a class="header-anchor" href="#_3-响应角色" aria-label="Permalink to &quot;3. 响应角色&quot;">​</a></h2><h3 id="_3-1-incident-commander" tabindex="-1">3.1 Incident Commander <a class="header-anchor" href="#_3-1-incident-commander" aria-label="Permalink to &quot;3.1 Incident Commander&quot;">​</a></h3><p>IC 负责流程和决策，不应同时深挖代码：</p><ul><li>确认级别、目标和角色。</li><li>排定调查和缓解优先级。</li><li>控制高风险操作和冲突变更。</li><li>确定下一决策点和更新节奏。</li><li>宣布降级、恢复与结束。</li></ul><p>IC 不需要是最资深技术人员，但要有组织事故的授权。</p><h3 id="_3-2-operations-lead" tabindex="-1">3.2 Operations Lead <a class="header-anchor" href="#_3-2-operations-lead" aria-label="Permalink to &quot;3.2 Operations Lead&quot;">​</a></h3><p>Operations 负责技术执行：收集证据、形成假设、执行已批准缓解并验证结果。多人参与时由 lead 分派互不重复的调查支线。</p><h3 id="_3-3-communications-lead" tabindex="-1">3.3 Communications Lead <a class="header-anchor" href="#_3-3-communications-lead" aria-label="Permalink to &quot;3.3 Communications Lead&quot;">​</a></h3><p>Communications 将内部事实转成面向员工、客服和用户的稳定更新，避免技术调查者被反复询问打断。对外内容由授权人员发布，安全/隐私事件遵循法务和安全流程。</p><h3 id="_3-4-scribe" tabindex="-1">3.4 Scribe <a class="header-anchor" href="#_3-4-scribe" aria-label="Permalink to &quot;3.4 Scribe&quot;">​</a></h3><p>Scribe 记录时间、事实、决策、命令/变更链接和结果。记录不是逐字会议纪要，而是可复建事件的证据链。</p><h3 id="_3-5-填写后的角色表" tabindex="-1">3.5 填写后的角色表 <a class="header-anchor" href="#_3-5-填写后的角色表" aria-label="Permalink to &quot;3.5 填写后的角色表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>人员</th><th>当前任务</th></tr></thead><tbody><tr><td>IC</td><td>王宁</td><td>控制 SEV2 流程，14:20 更新</td></tr><tr><td>Operations lead</td><td>李明</td><td>验证 release 与失败 chunk 关系</td></tr><tr><td>CDN investigator</td><td>陈杰</td><td>检查资源删除和各 region 状态</td></tr><tr><td>Communications</td><td>赵岚</td><td>内部/状态页更新</td></tr><tr><td>Scribe</td><td>张悦</td><td>维护事实、决策和时间线</td></tr></tbody></table><p>小事故可以一人兼任多个角色，但 IC 与高风险操作执行者尽量分开。影响扩大时立即拆分。</p><h2 id="_4-分诊与调查" tabindex="-1">4. 分诊与调查 <a class="header-anchor" href="#_4-分诊与调查" aria-label="Permalink to &quot;4. 分诊与调查&quot;">​</a></h2><h3 id="_4-1-建立变更窗口" tabindex="-1">4.1 建立变更窗口 <a class="header-anchor" href="#_4-1-建立变更窗口" aria-label="Permalink to &quot;4.1 建立变更窗口&quot;">​</a></h3><p>先查看影响开始前后 30–60 分钟：应用 release、配置、CDN、BFF、依赖服务和证书变化。变更只是调查线索，不应直接认定“最后一次发布就是原因”。</p><p>事故期间冻结无关生产变更，避免新变量进入。紧急修复必须绑定事故 ID 并由 IC 批准。</p><h3 id="_4-2-分层定位" tabindex="-1">4.2 分层定位 <a class="header-anchor" href="#_4-2-分层定位" aria-label="Permalink to &quot;4.2 分层定位&quot;">​</a></h3><p>前端旅程按层检查：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTML/启动配置</span></span>
<span class="line"><span>  → JS/CSS/动态 chunk</span></span>
<span class="line"><span>  → 浏览器运行与状态</span></span>
<span class="line"><span>  → API/BFF</span></span>
<span class="line"><span>  → 下游服务</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>每一层用一个可证伪问题推进。例如“失败 chunk 直接请求是否 404？”比“CDN 是不是坏了？”更容易得到事实。</p><h3 id="_4-3-对照组" tabindex="-1">4.3 对照组 <a class="header-anchor" href="#_4-3-对照组" aria-label="Permalink to &quot;4.3 对照组&quot;">​</a></h3><p>选择正常与异常对照：</p><ul><li>新会话与发布前已打开会话。</li><li>当前 release 与上一 release。</li><li>受影响 region 与正常 region。</li><li>某浏览器主版本与其他版本。</li><li>真实用户与合成探针。</li></ul><p>对照能快速缩小范围，但避免查询高基数维度拖垮观测平台。</p><h3 id="_4-4-保存证据" tabindex="-1">4.4 保存证据 <a class="header-anchor" href="#_4-4-保存证据" aria-label="Permalink to &quot;4.4 保存证据&quot;">​</a></h3><p>保存不可变引用：错误事件 ID、dashboard 时间范围、发布记录、配置版本、HTTP headers、受影响资源 URL 和操作审计。不要截图替代所有原始查询；截图无法重算且容易缺少时区和过滤条件。</p><p>安全事件不要在未授权频道粘贴敏感 payload，应升级安全响应并遵循证据保全要求。</p><h2 id="_5-缓解与恢复" tabindex="-1">5. 缓解与恢复 <a class="header-anchor" href="#_5-缓解与恢复" aria-label="Permalink to &quot;5. 缓解与恢复&quot;">​</a></h2><h3 id="_5-1-先降低影响" tabindex="-1">5.1 先降低影响 <a class="header-anchor" href="#_5-1-先降低影响" aria-label="Permalink to &quot;5.1 先降低影响&quot;">​</a></h3><p>候选动作按“速度、可逆性、已验证程度、附加风险”排序：</p><table tabindex="0"><thead><tr><th>动作</th><th>适用情况</th><th>主要风险</th></tr></thead><tbody><tr><td>切回已知 release</td><td>新版本高度相关且旧版仍兼容</td><td>旧版与当前 API/config 不兼容</td></tr><tr><td>关闭 Feature Flag</td><td>故障能力受开关保护</td><td>开关传播延迟或覆盖不全</td></tr><tr><td>降级到只读/简化路径</td><td>核心读取可保留</td><td>用户能力受限、数据稍旧</td></tr><tr><td>恢复缺失静态资源</td><td>已确认资源集合和完整性</td><td>上传错误版本造成混合制品</td></tr><tr><td>扩容/限流</td><td>容量或流量过载</td><td>掩盖泄漏、增加成本</td></tr></tbody></table><p>复杂热修通常慢且未经验证，应在可逆缓解不可用时再考虑。</p><h3 id="_5-2-操作前-brief" tabindex="-1">5.2 操作前 Brief <a class="header-anchor" href="#_5-2-操作前-brief" aria-label="Permalink to &quot;5.2 操作前 Brief&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>动作：恢复上一 release 7bd221e 的完整静态资源并切换 active 指针</span></span>
<span class="line"><span>目的：让旧会话和新页面都能加载匹配 chunk</span></span>
<span class="line"><span>执行：陈杰    审核：王宁</span></span>
<span class="line"><span>开始：14:12 CST</span></span>
<span class="line"><span>预期：2 分钟内完成；5 分钟内错误率下降</span></span>
<span class="line"><span>回退：若错误扩大，切回 8f3c41a 并停止资源清理任务</span></span>
<span class="line"><span>验证：chunk URL 200；合成导出通过；5 分钟会话错误率 &lt; 0.1%</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>执行者复述命令目标，审核者确认环境和 release，避免压力下操作错集群或路径。</p><h3 id="_5-3-一次改变一个主要变量" tabindex="-1">5.3 一次改变一个主要变量 <a class="header-anchor" href="#_5-3-一次改变一个主要变量" aria-label="Permalink to &quot;5.3 一次改变一个主要变量&quot;">​</a></h3><p>同时回滚、清缓存、改配置和重启服务会失去因果观察，也可能产生新故障。除非 SEV1 需要并行止血，IC 应明确每个动作的时间、预期和观察窗口。</p><h3 id="_5-4-验证恢复" tabindex="-1">5.4 验证恢复 <a class="header-anchor" href="#_5-4-验证恢复" aria-label="Permalink to &quot;5.4 验证恢复&quot;">​</a></h3><p>缓解命令成功不等于用户恢复。按顺序验证：</p><ol><li>制品/配置状态是目标版本。</li><li>直接请求此前失败的资源或 API 成功。</li><li>合成关键旅程成功。</li><li>真实用户 SLI 和错误率恢复。</li><li>不同地区、浏览器和旧会话没有残余影响。</li><li>观察窗口内无反弹。</li></ol><h3 id="_5-5-监控期" tabindex="-1">5.5 监控期 <a class="header-anchor" href="#_5-5-监控期" aria-label="Permalink to &quot;5.5 监控期&quot;">​</a></h3><p>恢复后保留角色和频道一段时间。明确：观察到几点、谁盯哪些指标、什么阈值会重新打开。不要立即解散后让反弹告警重新从值班链路开始。</p><h2 id="_6-沟通" tabindex="-1">6. 沟通 <a class="header-anchor" href="#_6-沟通" aria-label="Permalink to &quot;6. 沟通&quot;">​</a></h2><h3 id="_6-1-更新格式" tabindex="-1">6.1 更新格式 <a class="header-anchor" href="#_6-1-更新格式" aria-label="Permalink to &quot;6.1 更新格式&quot;">​</a></h3><p>每次更新固定四项：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前影响：什么用户无法做什么</span></span>
<span class="line"><span>已知事实：已验证的信息</span></span>
<span class="line"><span>正在做：当前缓解/调查动作</span></span>
<span class="line"><span>下一更新：明确时间，即使没有新结论也更新</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>避免承诺未经验证的恢复时间。可以说“14:20 前给下一次进展”，不要说“10 分钟一定修好”。</p><h3 id="_6-2-内部更新示例" tabindex="-1">6.2 内部更新示例 <a class="header-anchor" href="#_6-2-内部更新示例" aria-label="Permalink to &quot;6.2 内部更新示例&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[14:10 CST][SEV2][INC-2026-0729-01]</span></span>
<span class="line"><span>影响：约 17.6% 活跃会话进入分析页或批量导出时遇到动态模块加载失败；订单查看正常。</span></span>
<span class="line"><span>事实：失败资源返回 404，hash 属于上一 release；13:55 有前端部署。</span></span>
<span class="line"><span>动作：正在验证上一不可变制品，准备恢复其完整资源。当前暂停其他 order-web 发布。</span></span>
<span class="line"><span>下一更新：14:20 CST。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_6-3-用户状态页示例" tabindex="-1">6.3 用户状态页示例 <a class="header-anchor" href="#_6-3-用户状态页示例" aria-label="Permalink to &quot;6.3 用户状态页示例&quot;">​</a></h3><p>调查中：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我们正在调查订单工作台部分页面和批量导出无法加载的问题。订单查看不受影响。下一次更新将在 20 分钟内提供。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>恢复后：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>订单工作台页面加载已于 14:21 CST 恢复。我们将继续监控，并在完成分析后更新事件说明。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>对外沟通描述事实和用户选择，不发布内部主机、个人信息、攻击细节或未经确认原因。</p><h3 id="_6-4-沟通频率" tabindex="-1">6.4 沟通频率 <a class="header-anchor" href="#_6-4-沟通频率" aria-label="Permalink to &quot;6.4 沟通频率&quot;">​</a></h3><p>SEV1 通常 10–15 分钟，SEV2 15–30 分钟；具体按组织标准。即使没有进展，也说明“影响未变化、当前调查项、下一更新”。沉默会让客服和业务团队重复打断响应者。</p><h2 id="_7-时间线与决策记录" tabindex="-1">7. 时间线与决策记录 <a class="header-anchor" href="#_7-时间线与决策记录" aria-label="Permalink to &quot;7. 时间线与决策记录&quot;">​</a></h2><h3 id="_7-1-时间标准" tabindex="-1">7.1 时间标准 <a class="header-anchor" href="#_7-1-时间标准" aria-label="Permalink to &quot;7.1 时间标准&quot;">​</a></h3><p>事故开始时声明统一时区，例如 CST（UTC+8），系统事件保留原始 UTC 时间。相对描述“刚才”“大概十分钟前”必须转换为时间戳。</p><h3 id="_7-2-记录类型" tabindex="-1">7.2 记录类型 <a class="header-anchor" href="#_7-2-记录类型" aria-label="Permalink to &quot;7.2 记录类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>示例</th></tr></thead><tbody><tr><td>DETECT</td><td>告警触发、用户报告</td></tr><tr><td>FACT</td><td>查询确认的事实</td></tr><tr><td>HYPOTHESIS</td><td>待验证解释</td></tr><tr><td>DECISION</td><td>IC 批准的选择及依据</td></tr><tr><td>ACTION</td><td>生产操作和执行者</td></tr><tr><td>RESULT</td><td>动作后的可观察结果</td></tr><tr><td>COMMS</td><td>内外部更新</td></tr></tbody></table><h3 id="_7-3-填写后的时间线" tabindex="-1">7.3 填写后的时间线 <a class="header-anchor" href="#_7-3-填写后的时间线" aria-label="Permalink to &quot;7.3 填写后的时间线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 CST</th><th>类型</th><th>记录</th></tr></thead><tbody><tr><td>13:55</td><td>FACT</td><td>order-web@8f3c41a production 部署完成</td></tr><tr><td>13:58</td><td>FACT</td><td>后续回算的最早受影响会话</td></tr><tr><td>14:02</td><td>DETECT</td><td>chunk load SLO 告警触发</td></tr><tr><td>14:03</td><td>ACTION</td><td>Primary 李明确认告警</td></tr><tr><td>14:05</td><td>DECISION</td><td>声明 SEV2，王宁担任 IC</td></tr><tr><td>14:08</td><td>FACT</td><td>失败 URL 均为前一 release hash，HTTP 404</td></tr><tr><td>14:12</td><td>DECISION</td><td>恢复 7bd221e 完整制品并切换指针</td></tr><tr><td>14:16</td><td>RESULT</td><td>制品恢复完成，直接请求返回 200</td></tr><tr><td>14:18</td><td>RESULT</td><td>合成分析页与批量导出入口通过</td></tr><tr><td>14:21</td><td>RESULT</td><td>真实会话错误率连续 5 分钟低于 0.1%</td></tr><tr><td>14:30</td><td>COMMS</td><td>状态页标记已恢复，进入 30 分钟观察</td></tr><tr><td>15:00</td><td>DECISION</td><td>结束事故，指定复盘 owner 张悦</td></tr></tbody></table><p>时间线在事故中记录事实，复盘可以补充来源，但不能事后删除看起来“不正确”的当时假设；应标明其被证伪时间。</p><h2 id="_8-结束与移交" tabindex="-1">8. 结束与移交 <a class="header-anchor" href="#_8-结束与移交" aria-label="Permalink to &quot;8. 结束与移交&quot;">​</a></h2><h3 id="_8-1-恢复声明" tabindex="-1">8.1 恢复声明 <a class="header-anchor" href="#_8-1-恢复声明" aria-label="Permalink to &quot;8.1 恢复声明&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>恢复时间：2026-07-29 14:21 CST</span></span>
<span class="line"><span>恢复证据：</span></span>
<span class="line"><span>- chunk load failure rate 5 分钟 &lt; 0.1%</span></span>
<span class="line"><span>- staging/production 合成关键路由通过</span></span>
<span class="line"><span>- 华东、华南直接资源请求均为 200</span></span>
<span class="line"><span>当前版本：order-web@7bd221e</span></span>
<span class="line"><span>观察至：15:00 CST</span></span>
<span class="line"><span>观察 owner：李明</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>若数据补偿、客户通知或资源恢复仍未完成，事故可以“服务恢复但后续工作开放”，不能把两者混成完全结束。</p><h3 id="_8-2-结束前清理" tabindex="-1">8.2 结束前清理 <a class="header-anchor" href="#_8-2-结束前清理" aria-label="Permalink to &quot;8.2 结束前清理&quot;">​</a></h3><ul><li>解除事故期间的无关变更冻结。</li><li>检查临时权限和调试开关到期。</li><li>为任何 silence 设置恢复或明确到期。</li><li>把临时脚本和查询链接保存到受控位置。</li><li>创建复盘和待办，不在频道消息中遗失。</li></ul><h3 id="_8-3-复盘触发" tabindex="-1">8.3 复盘触发 <a class="header-anchor" href="#_8-3-复盘触发" aria-label="Permalink to &quot;8.3 复盘触发&quot;">​</a></h3><p>SEV1/SEV2、接近更高级别的 near miss、重复事故或暴露系统性缺口的 SEV3 都应复盘。复盘 owner、评审时间和初始证据在结束事故时确定。</p><h3 id="_8-4-响应指标" tabindex="-1">8.4 响应指标 <a class="header-anchor" href="#_8-4-响应指标" aria-label="Permalink to &quot;8.4 响应指标&quot;">​</a></h3><p>本案例：</p><table tabindex="0"><thead><tr><th>指标</th><th>结果</th><th>口径</th></tr></thead><tbody><tr><td>Time to detect</td><td>4 分钟</td><td>13:58 首次影响至 14:02 告警</td></tr><tr><td>Time to acknowledge</td><td>1 分钟</td><td>告警至 Primary ack</td></tr><tr><td>Time to declare</td><td>3 分钟</td><td>ack 至声明事故</td></tr><tr><td>Time to mitigate</td><td>18 分钟</td><td>首次影响至资源恢复完成</td></tr><tr><td>Time to recover</td><td>23 分钟</td><td>首次影响至 SLI 确认恢复</td></tr><tr><td>首次用户通告</td><td>8 分钟</td><td>声明至状态页首次更新</td></tr></tbody></table><p>时间指标用于发现流程和系统改进，不用于排名个人。单纯压缩“确认时间”可能鼓励无意义 ack。</p><h2 id="_9-常见反模式" tabindex="-1">9. 常见反模式 <a class="header-anchor" href="#_9-常见反模式" aria-label="Permalink to &quot;9. 常见反模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>反模式</th><th>后果</th><th>修正</th></tr></thead><tbody><tr><td>私聊排障</td><td>无共享上下文，无法增援</td><td>尽早声明并进入事故频道</td></tr><tr><td>IC 同时执行所有命令</td><td>决策、沟通和操作均阻塞</td><td>分离角色</td></tr><tr><td>根因未明就拒绝回滚</td><td>用户影响持续</td><td>优先可逆缓解</td></tr><tr><td>同时做多个高风险改变</td><td>无法判断效果，可能二次故障</td><td>明确动作和观察窗口</td></tr><tr><td>状态页写未经确认原因</td><td>后续更正损害信任</td><td>只写事实和影响</td></tr><tr><td>图表回落立即关闭</td><td>延迟上报或地区残留被忽略</td><td>多信号和观察期</td></tr><tr><td>用 MTTR 考核个人</td><td>隐瞒事故、草率操作</td><td>用于系统学习</td></tr></tbody></table><h2 id="_10-参考资料" tabindex="-1">10. 参考资料 <a class="header-anchor" href="#_10-参考资料" aria-label="Permalink to &quot;10. 参考资料&quot;">​</a></h2><ul><li><a href="https://sre.google/sre-book/managing-incidents/" target="_blank" rel="noreferrer">Google SRE：Managing Incidents</a></li><li><a href="https://sre.google/workbook/incident-response/" target="_blank" rel="noreferrer">Google SRE Workbook：Incident Response</a></li><li><a href="https://response.pagerduty.com/" target="_blank" rel="noreferrer">PagerDuty：Incident Response</a></li><li><a href="https://www.atlassian.com/incident-management/incident-response" target="_blank" rel="noreferrer">Atlassian：Incident response</a></li><li><a href="https://csrc.nist.gov/pubs/sp/800/61/r3/final" target="_blank" rel="noreferrer">NIST SP 800-61r3：Incident Response Recommendations</a></li></ul>`,118)])])}const u=t(r,[["render",l]]);export{b as __pageData,u as default};
